-- 30 базовых вопросов об объектах PostgreSQL 16 с пояснениями к каждому варианту.
-- Источник: scripts/questions/030_database_object_basics.js
-- Повторный запуск безопасен; несовпадение ранее добавленного вопроса отменяет пакет.
-- https://www.postgresql.org/docs/16/sql-createfunction.html
-- https://www.postgresql.org/docs/16/xproc.html
-- https://www.postgresql.org/docs/16/sql-call.html
-- https://www.postgresql.org/docs/16/trigger-definition.html
-- https://www.postgresql.org/docs/16/indexes-intro.html
-- https://www.postgresql.org/docs/16/indexes-unique.html
-- https://www.postgresql.org/docs/16/indexes-types.html
-- https://www.postgresql.org/docs/16/indexes-expressional.html
-- https://www.postgresql.org/docs/16/indexes-partial.html
-- https://www.postgresql.org/docs/16/sql-createview.html
-- https://www.postgresql.org/docs/16/rules-materializedviews.html
-- https://www.postgresql.org/docs/16/sql-refreshmaterializedview.html
-- https://www.postgresql.org/docs/16/sql-createsequence.html
-- https://www.postgresql.org/docs/16/functions-sequence.html
