-- https://www.postgresql.org/docs/16/ddl-constraints.html#DDL-CONSTRAINTS-CHECK-CONSTRAINTS
-- https://www.postgresql.org/docs/16/ddl-constraints.html#DDL-CONSTRAINTS-UNIQUE-CONSTRAINTS

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMP TABLE question_seed (
    category_id integer NOT NULL,
    question_text text NOT NULL UNIQUE,
    options jsonb NOT NULL,
    correct_answer text NOT NULL,
    explanation text NOT NULL,
    option_notes jsonb NOT NULL
) ON COMMIT DROP;

INSERT INTO question_seed
SELECT (SELECT id FROM categories WHERE left(name, 3) = '04.'), 'Что такое пользовательская функция в PostgreSQL?', '{"A":"Именованная подпрограмма на сервере с объявленным типом результата, которую можно вызвать из SQL","B":"Сохранённая копия всех строк таблицы на момент резервного копирования","C":"Параметр конфигурации, действующий только до конца транзакции","D":"Любая команда операционной системы, запускающая сервер"}'::jsonb, 'A', 'Функция объединяет действия под именем и имеет объявленный тип результата. Если содержательный результат не нужен, можно использовать тип void.', '{"A":"Функция создаётся в базе; её аргументы и результат описываются при объявлении.","B":"Это описание копии данных, а не подпрограммы.","C":"Параметры управляют работой сервера и не являются функциями.","D":"Серверные утилиты ОС и функции базы — разные объекты."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '04.'), 'В базе определена функция app.add_tax(numeric), возвращающая numeric. Что делает запрос SELECT app.add_tax(100);?', '{"A":"Переименовывает аргумент функции в 100","B":"Обязательно добавляет 100 строк в таблицу app","C":"Создаёт новую функцию с именем add_tax","D":"Вызывает функцию с аргументом 100 и выводит её результат"}'::jsonb, 'D', 'Квалифицированное имя app.add_tax указывает схему и функцию. Значение 100 передаётся аргументом, а возвращаемое значение становится результатом выражения.', '{"A":"100 — передаваемое значение, а не новое имя аргумента.","B":"app здесь имя схемы; действие определяется телом функции.","C":"Функции создаёт CREATE FUNCTION.","D":"Вызов функции используется как выражение в SELECT."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '04.'), 'Какие формы результата может иметь пользовательская функция PostgreSQL при соответствующем объявлении?', '{"A":"Только целое число, используемое как код завершения ОС","B":"Всегда ровно одну строку: наборы строк запрещены","C":"Все пользовательские функции PostgreSQL обязаны возвращать boolean","D":"Одно значение, например integer или text","E":"Набор строк, например через RETURNS TABLE"}'::jsonb, 'DE', 'Объявление функции определяет форму результата. Это может быть скалярное значение, составное значение или набор строк.', '{"A":"Функции SQL не ограничены моделью кодов завершения процессов.","B":"RETURNS SETOF и RETURNS TABLE позволяют возвращать наборы.","C":"Тип результата задаётся объявлением функции и не ограничен boolean.","D":"Скалярный результат задаётся через RETURNS с подходящим типом.","E":"Функция может возвращать множество строк с заданными столбцами."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '04.'), 'Что такое процедура, создаваемая командой CREATE PROCEDURE?', '{"A":"Обычное представление, которое обязательно хранит строки на диске","B":"Синоним функции, которую всегда вызывают только внутри SELECT","C":"Хранимая подпрограмма для выполнения действий, вызываемая командой CALL","D":"Фоновый процесс, автоматически создаваемый для каждой таблицы"}'::jsonb, 'C', 'Процедура выполняет серверный код через CALL. У неё нет предложения RETURNS как у функции, но она может передавать результаты через выходные параметры.', '{"A":"Представление и процедура имеют разное назначение.","B":"Для процедуры используется CALL, а не вызов как выражения SELECT.","C":"Процедура — самостоятельный вид подпрограммы базы данных.","D":"Определение процедуры не создаёт постоянно работающий процесс."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '04.'), 'Как вызвать существующую процедуру app.rebuild_summary без параметров?', '{"A":"`CALL app.rebuild_summary();`","B":"`EXECUTE app.rebuild_summary();`","C":"`REFRESH app.rebuild_summary();`","D":"`SELECT app.rebuild_summary();`"}'::jsonb, 'A', 'Процедура вызывается отдельной командой CALL. Перед вызовом должны существовать сама процедура и необходимые права доступа.', '{"A":"CALL предназначен для вызова процедур.","B":"SQL-команда EXECUTE выполняет подготовленный оператор.","C":"Такой команды вызова процедуры нет.","D":"Такая форма вызывает функцию, а не процедуру."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '04.'), 'Что такое триггер в PostgreSQL?', '{"A":"Копия таблицы, обновляемая после каждой резервной копии","B":"Подпрограмма, которая срабатывает исключительно по расписанию часов","C":"Объект, связывающий событие в базе с автоматическим вызовом триггерной функции","D":"Указатель на каталог, в котором хранятся файлы таблиц"}'::jsonb, 'C', 'Триггер определяет событие и условия вызова функции. Обычные триггеры таблиц могут реагировать, например, на INSERT, UPDATE и DELETE.', '{"A":"Триггер не является копией данных.","B":"Триггеры привязаны к событиям базы, а не к расписанию ОС.","C":"Например, изменение строки таблицы может запускать заданную функцию.","D":"Такое назначение связано с табличными пространствами."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '04.'), 'На обычной несекционированной таблице есть один включённый триггер AFTER UPDATE FOR EACH ROW без WHEN, его функция не выполняет действий, вызывающих повторное срабатывание. Одна команда UPDATE изменила 10 строк, других триггеров нет. Сколько раз он сработает?', '{"A":"10 раз — по одному разу для каждой изменённой строки","B":"Один раз — независимо от числа изменённых строк","C":"Ни разу, потому что AFTER означает только после COMMIT","D":"Столько раз, сколько всего строк в таблице"}'::jsonb, 'A', 'Построчный триггер вызывается для каждой затронутой строки. Триггер уровня оператора, напротив, вызывается один раз для команды даже при отсутствии затронутых строк.', '{"A":"FOR EACH ROW задаёт построчный вызов.","B":"Это соответствовало бы FOR EACH STATEMENT.","C":"Обычный AFTER-триггер не означает ожидание фиксации транзакции.","D":"Учитываются строки, затронутые командой, а не вся таблица."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '04.'), 'Какие утверждения об обычных триггерах таблиц верны?', '{"A":"Для любой проверки NOT NULL обязательно писать свой триггер","B":"BEFORE INSERT FOR EACH ROW может изменить значения NEW перед вставкой","C":"AFTER-триггер всегда работает в новой транзакции после COMMIT","D":"Триггер срабатывает только после ручной команды CALL","E":"Триггерная функция выполняется в той же транзакции, что и вызвавшая её команда"}'::jsonb, 'BE', 'BEFORE-триггеры позволяют обработать строку до изменения таблицы. Триггеры и вызвавшая их команда участвуют в одной транзакции.', '{"A":"NOT NULL обеспечивается встроенным ограничением.","B":"Триггерная функция может вернуть изменённую новую строку.","C":"Обычный AFTER-триггер не создаёт отдельную транзакцию после фиксации.","D":"Срабатывание определяется событием, указанным при создании триггера.","E":"Её изменения не становятся отдельной независимо фиксируемой транзакцией."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '04.'), 'Для чего в базе данных нужен индекс?', '{"A":"Для обязательного хранения второй полной копии всех столбцов таблицы","B":"Для гарантированного ускорения каждого запроса без дополнительных затрат","C":"Для дополнительного пути доступа, который может ускорить поиск нужных строк","D":"Для замены любых ограничений целостности"}'::jsonb, 'C', 'Индекс — вспомогательная структура доступа. Его полезность зависит от запроса, данных и оценки стоимости плана.', '{"A":"Индекс не обязан содержать все столбцы и не является резервной копией таблицы.","B":"Индекс полезен не всегда, занимает место и требует обслуживания.","C":"Подходящий индекс позволяет избежать просмотра всей таблицы в некоторых запросах.","D":"Например, индекс сам по себе не заменяет внешний ключ или CHECK."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '04.'), 'На столбце есть подходящий индекс, но PostgreSQL выбирает последовательное сканирование таблицы. Обязательно ли это ошибка?', '{"A":"Нет: индексы вообще не применяются в SELECT","B":"Да: любой существующий индекс обязан использоваться во всех запросах","C":"Нет: планировщик мог оценить последовательное сканирование как более дешёвое","D":"Да: после создания любого индекса сервер нужно перезапустить"}'::jsonb, 'C', 'Последовательное сканирование может быть рациональным выбором. Для оценки причин смотрят план запроса и актуальность статистики.', '{"A":"Индексы активно используются для чтения, когда это выгодно.","B":"Планировщик выбирает план, а не использует индекс только из-за его наличия.","C":"Например, при чтении большой доли таблицы индекс может не дать выигрыша.","D":"Штатное создание индекса не требует перезапуска."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '04.'), 'На email создан обычный уникальный индекс без условия WHERE. Что произойдёт при попытке вставить вторую строку с тем же ненулевым email обычным INSERT без ON CONFLICT, если триггеры не изменяют и не отменяют вставляемую строку?', '{"A":"Новая строка автоматически заменит существующую","B":"Индекс будет автоматически удалён","C":"Вставка будет отклонена из-за нарушения уникальности","D":"Дубликат будет разрешён до следующего VACUUM"}'::jsonb, 'C', 'Уникальный индекс обеспечивает уникальность индексируемого ключа. В вопросе обе строки имеют одинаковое значение email, отличное от NULL.', '{"A":"Без явно заданной обработки конфликта замены не происходит.","B":"Конфликт данных не удаляет индекс.","C":"Уникальный индекс не допускает одинаковые ненулевые ключи.","D":"Проверка уникальности не откладывается до очистки."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '04.'), 'Какой встроенный тип индекса обычно подходит для сравнений целых чисел как на равенство, так и на диапазон: =, <, <=, >, >=?', '{"A":"B-tree","B":"Любой индекс поддерживает только равенство","C":"Hash","D":"Для диапазонов индексы использовать нельзя"}'::jsonb, 'A', 'B-tree — тип индекса по умолчанию в CREATE INDEX. Это типичный выбор для упорядоченных сравнений числовых значений.', '{"A":"B-tree поддерживает равенство и упорядоченные диапазоны для таких значений.","B":"Поддерживаемые операции зависят от метода доступа.","C":"Hash-индекс поддерживает сравнение на равенство, но не поиск по диапазону.","D":"Диапазонный поиск — обычное применение B-tree."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '04.'), 'Какие затраты нужно учитывать при добавлении индексов к активно изменяемой таблице?', '{"A":"Индексы делают любую запись быстрее, потому что таблица больше не изменяется","B":"Вставки и часть других изменений требуют обслуживания индексов","C":"После создания индекса все строки таблицы обязательно помещаются в оперативную память","D":"Индексы занимают дополнительное место на диске","E":"Индекс автоматически избавляет таблицу от необходимости VACUUM"}'::jsonb, 'BD', 'Индексы выбирают под нагрузку: они могут ускорить чтение, но требуют дискового пространства и обновления при изменении данных.', '{"A":"Таблица продолжает изменяться, а индексы могут добавлять работу.","B":"Ускорение чтения может сопровождаться дополнительной работой при записи.","C":"Индекс не гарантирует размещение всей таблицы в памяти.","D":"Каждый индекс хранит свою структуру данных.","E":"Наличие индекса не отменяет очистку таблицы и индексов."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '04.'), 'Какие варианты индексов поддерживает PostgreSQL?', '{"A":"Индекс по выражению, например lower(email)","B":"Частичный индекс только по строкам, удовлетворяющим условию WHERE","C":"Только индексы по одному столбцу, выражения и условия запрещены","D":"Индекс, объединяющий строки таблиц из двух разных баз кластера","E":"Индекс, автоматически обновляющий материализованное представление при каждой записи"}'::jsonb, 'AB', 'Индекс по выражению и частичный индекс решают разные задачи: первый меняет индексируемое значение, второй ограничивает набор строк.', '{"A":"Индекс может хранить результат допустимого выражения, а не только значение столбца.","B":"Предикат задаёт подмножество индексируемых строк.","C":"Поддерживаются и выражения, и частичные, и многоколоночные индексы.","D":"Обычный индекс строится для конкретной таблицы, а не между базами.","E":"Создание индекса не добавляет такой механизм обновления."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Что такое обычное представление (VIEW) в PostgreSQL?', '{"A":"Именованный запрос, к результату которого можно обращаться как к таблице","B":"Отдельная база данных внутри текущей схемы","C":"Физическая копия таблицы, которая никогда не меняется","D":"Обязательный индекс для каждой таблицы"}'::jsonb, 'A', 'CREATE VIEW сохраняет определение запроса под именем. При обращении к представлению PostgreSQL использует этот запрос для получения результата.', '{"A":"Сохраняется определение запроса; обычное представление не хранит отдельную копию результата.","B":"Схема принадлежит базе; представление не создаёт вложенную базу.","C":"Обычное представление получает данные из своего запроса.","D":"Представление и индекс — разные объекты."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Есть автоматически обновляемое представление CREATE VIEW active_users AS SELECT id, active FROM users WHERE active; Выполняют DELETE FROM active_users WHERE id = 7; Видимая строка с id = 7 существует, права есть, мешающих ограничений и триггеров нет. Что удалится?', '{"A":"Все строки users независимо от условия","B":"Только сохранённая копия строки внутри представления","C":"Соответствующая строка из базовой таблицы users","D":"Само определение представления active_users"}'::jsonb, 'C', 'Простые представления могут быть автоматически обновляемыми. DELETE через такое представление удаляет строки базовой таблицы, удовлетворяющие условию представления и условию DELETE.', '{"A":"Учитываются условие представления и условие DELETE.","B":"У обычного представления нет отдельного хранилища этих строк.","C":"Для такого представления изменение перенаправляется в базовую таблицу.","D":"Определение удаляется командой DROP VIEW, а не DELETE."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Для каких задач подходит обычное представление?', '{"A":"Предоставить запросам выбранный набор столбцов и строк","B":"Автоматически хранить результат сложного запроса на диске и читать его без пересчёта","C":"Дать имя часто используемому запросу с соединением таблиц","D":"Заменить резервную копию исходных таблиц"}'::jsonb, 'AC', 'Представления помогают переиспользовать SQL и задавать удобную форму доступа к данным. Ограничение доступа требует также правильно настроенных прав.', '{"A":"Определение представления может содержать проекцию столбцов и фильтр WHERE.","B":"Обычное представление не материализует результат.","C":"Так можно скрыть повторяющийся SQL за именем представления.","D":"Сохранённое определение запроса не является копией данных."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Чем материализованное представление отличается от обычного представления?', '{"A":"Не имеет определяющего запроса","B":"Хранит результат запроса как данные, которые можно обновить отдельной командой","C":"Всегда пересчитывает весь запрос при каждом SELECT","D":"Является другим названием временной таблицы","E":"Может существовать только в памяти одного клиентского приложения"}'::jsonb, 'B', 'Материализованное представление сохраняет и определение запроса, и его результат. Это позволяет обменять актуальность данных на экономию повторных вычислений.', '{"A":"Запрос сохраняется и используется при обновлении результата.","B":"Сохранённый результат позволяет читать уже вычисленные строки.","C":"SELECT обычно читает сохранённый результат.","D":"Материализованное представление не ограничено сроком одного сеанса.","E":"Это объект базы данных на сервере."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Как заново вычислить и сохранить данные существующего материализованного представления monthly_sales?', '{"A":"`REFRESH VIEW monthly_sales;`","B":"`ANALYZE monthly_sales;`","C":"`REINDEX TABLE monthly_sales;`","D":"`REFRESH MATERIALIZED VIEW monthly_sales;`","E":"`SELECT pg_reload_conf();`"}'::jsonb, 'D', 'REFRESH MATERIALIZED VIEW заменяет сохранённое содержимое результатом нового выполнения определяющего запроса.', '{"A":"Нужна форма REFRESH MATERIALIZED VIEW.","B":"ANALYZE собирает статистику для планировщика, а не пересчитывает результат запроса.","C":"REINDEX перестраивает индексы, а не данные определяющего запроса.","D":"Команда обновляет содержимое по сохранённому запросу.","E":"Перечитывание конфигурации не обновляет материализованные представления."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Какие утверждения о материализованном представлении в PostgreSQL 16 верны?', '{"A":"После изменения исходных таблиц его данные могут оставаться устаревшими до обновления","B":"Любой INSERT в исходную таблицу автоматически вызывает REFRESH","C":"Сохранённый результат всегда совпадает с исходными таблицами без дополнительных действий","D":"На нём можно создавать индексы"}'::jsonb, 'AD', 'Материализованное представление полезно для дорогих расчётов, когда допустимо периодическое обновление. Индексы на нём не обеспечивают автоматическую актуализацию данных.', '{"A":"Встроенный механизм не поддерживает результат автоматически при каждой записи в исходные таблицы.","B":"Такое поведение само по себе не появляется при создании материализованного представления.","C":"Актуальность зависит от момента обновления.","D":"Индексы могут ускорять запросы к сохранённым данным."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Что такое последовательность (SEQUENCE) в PostgreSQL?', '{"A":"Ограничение, запрещающее одинаковые значения во всех таблицах базы","B":"Список всех команд, выполненных одной транзакцией","C":"Обязательный порядок вывода строк любого SELECT","D":"Отдельный объект для выдачи числовых значений по заданным правилам"}'::jsonb, 'D', 'Последовательность хранит состояние генератора числовых значений. Шаг, границы и цикличность можно настроить; непрерывная нумерация без пропусков не гарантируется.', '{"A":"Последовательность сама по себе не проверяет уникальность данных таблиц.","B":"Последовательность не является журналом SQL-команд.","C":"Порядок результата запроса задаётся ORDER BY.","D":"Часто последовательность используют для получения идентификаторов строк."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Какой вызов выдаёт следующее значение существующей последовательности app.order_ids и продвигает её состояние?', '{"A":"`pg_get_serial_sequence(''app.orders'', ''id'')`","B":"`currval(''app.order_ids'')`","C":"`setval(''app.order_ids'', 100)`","D":"`lastval()`","E":"`nextval(''app.order_ids'')`"}'::jsonb, 'E', 'nextval изменяет состояние последовательности и возвращает очередное значение. Одновременные вызовы обслуживаются атомарно.', '{"A":"Возвращает имя последовательности, связанной со столбцом, а не очередное числовое значение.","B":"Возвращает сеансовое значение этой последовательности, не продвигая её; его же может установить setval с is_called = true.","C":"Явно устанавливает состояние, а не запрашивает очередное значение по обычным правилам.","D":"Возвращает сеансовое значение последовательности, для которой последним вызывался nextval; сама последовательность не продвигается.","E":"Атомарно получает следующее значение последовательности."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Транзакция получила значение через nextval, а затем выполнила ROLLBACK. Будет ли это значение автоматически возвращено последовательности для повторной выдачи?', '{"A":"Да, но только после VACUUM","B":"Да, любое изменение состояния последовательности откатывается вместе с таблицами","C":"Нет, потому что ROLLBACK после nextval вообще запрещён","D":"Нет, откат транзакции не отменяет уже выполненный nextval"}'::jsonb, 'D', 'Последовательности рассчитаны на конкурентную выдачу значений, а не на нумерацию без пропусков. Пропуски возможны, в частности, после отмены транзакции.', '{"A":"VACUUM не возвращает последовательности значения отменённых транзакций.","B":"Для nextval действует другое правило: полученное значение не возвращается при откате.","C":"Откат разрешён; он просто не отменяет выдачу значения.","D":"Из-за этого в нумерации могут появляться пропуски."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'В сеансе не вызывают setval. Какие утверждения о currval для конкретной последовательности верны?', '{"A":"До первого nextval этой последовательности в текущем сеансе currval выдаст ошибку","B":"currval всегда показывает последнее значение, выданное любому сеансу","C":"Чужой сеанс может вызвать nextval, не изменив результат нашего currval","D":"Каждый вызов currval продвигает последовательность на один шаг","E":"currval вычисляет MAX(id) в использующей последовательность таблице"}'::jsonb, 'AC', 'currval предоставляет сеансовое значение: чужие вызовы nextval не мешают узнать свой ранее полученный номер.', '{"A":"В сеансе ещё нет последнего значения nextval для этой последовательности.","B":"Это не глобальное значение для всех подключений.","C":"currval привязан к последнему nextval именно в текущем сеансе.","D":"Для продвижения используют nextval.","E":"Он не сканирует таблицу и не вычисляет максимальный идентификатор."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Что такое ограничение целостности таблицы?', '{"A":"Лимит времени выполнения любого SELECT","B":"Список ролей, которым разрешён вход в кластер","C":"Комментарий, который сервер никогда не проверяет","D":"Правило допустимости данных, которое PostgreSQL проверяет при соответствующих изменениях"}'::jsonb, 'D', 'Ограничения описывают правила данных: например, обязательность значения, уникальность или допустимость ссылки на другую строку.', '{"A":"Время выполнения регулируется другими механизмами, например statement_timeout.","B":"Это относится к доступу и аутентификации, а не к допустимости значений таблицы.","C":"Ограничение имеет исполняемую проверку, а не только описание.","D":"Ограничения защищают данные независимо от того, какое приложение отправило команду."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Что обеспечивает PRIMARY KEY для столбца или группы столбцов таблицы?', '{"A":"Автоматическую сортировку результатов всех запросов по ключу","B":"Обязательную ссылку на строку другой таблицы","C":"Уникальность ключа и запрет NULL в каждом его столбце","D":"Только автоматическую генерацию следующего номера"}'::jsonb, 'C', 'PRIMARY KEY сочетает уникальность и NOT NULL. Автоматическая выдача значений, например через identity, настраивается отдельно.', '{"A":"Порядок вывода задаётся ORDER BY.","B":"Такое назначение имеет FOREIGN KEY.","C":"Первичный ключ позволяет однозначно идентифицировать строку.","D":"Первичный ключ сам по себе не задаёт генератор значений."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Столбец orders.customer_id имеет немедленно проверяемый внешний ключ на customers.id. Что будет при вставке заказа с ненулевым customer_id, которого нет в customers?', '{"A":"Вставка будет отклонена из-за нарушения внешнего ключа","B":"customer_id автоматически станет NULL","C":"Вставка пройдёт, потому что внешние ключи проверяются только при SELECT","D":"Недостающий клиент автоматически создастся"}'::jsonb, 'A', 'FOREIGN KEY поддерживает ссылочную целостность. В условии проверка немедленная, поэтому неверная ссылка не откладывается до конца транзакции.', '{"A":"Ссылка должна соответствовать существующему значению в связанной таблице.","B":"При такой вставке автоматической замены значения не происходит.","C":"Внешний ключ контролирует соответствующие изменения данных.","D":"Внешний ключ не создаёт родительские строки."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'На price задано только CHECK (price > 0), ограничения NOT NULL нет. Допустима ли вставка NULL?', '{"A":"Да: CHECK не нарушается, если его выражение даёт NULL","B":"Нет: любое CHECK автоматически запрещает NULL","C":"Нет: при сравнении NULL > 0 всегда получается false","D":"Да, но NULL автоматически заменится на 0"}'::jsonb, 'A', 'CHECK отклоняет строку при результате false. Результаты true и NULL удовлетворяют ограничению, поэтому обязательность price задают отдельно.', '{"A":"CHECK (price > 0) сам по себе допускает NULL; чтобы запретить NULL, рекомендуется добавить NOT NULL.","B":"CHECK и NOT NULL — разные проверки.","C":"Результат такого сравнения — NULL, а не false.","D":"CHECK проверяет значение, а не подставляет замену."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Столбец допускает NULL. Какие утверждения об ограничении UNIQUE в PostgreSQL 16 верны?', '{"A":"UNIQUE NULLS NOT DISTINCT позволяет считать NULL равными при проверке уникальности","B":"UNIQUE допускает сколько угодно одинаковых ненулевых значений","C":"Поведение NULL в UNIQUE можно изменить только настройкой всего сервера","D":"Обычное UNIQUE по одному столбцу допускает несколько строк с NULL","E":"Любое UNIQUE автоматически добавляет NOT NULL"}'::jsonb, 'AD', 'Правило сравнения NULL при проверке уникальности можно выбрать явно. Это не то же самое, что запретить NULL через NOT NULL.', '{"A":"Для одного столбца это запрещает повторный NULL.","B":"Повторяющиеся ненулевые ключи нарушают уникальность.","C":"NULLS NOT DISTINCT указывается для конкретного ограничения или уникального индекса.","D":"По умолчанию NULL не считаются равными при такой проверке уникальности.","E":"Автоматический запрет NULL относится к PRIMARY KEY, а не к любому UNIQUE."}'::jsonb
UNION ALL
SELECT (SELECT id FROM categories WHERE left(name, 3) = '08.'), 'Какие утверждения о ключах, состоящих из нескольких столбцов, верны?', '{"A":"Имена столбцов внешнего ключа обязаны совпадать с именами столбцов, на которые он ссылается","B":"Для составного первичного ключа нужно объявить несколько независимых PRIMARY KEY","C":"FOREIGN KEY может ссылаться на комбинацию столбцов подходящего уникального ключа","D":"PRIMARY KEY (order_id, line_no) запрещает повтор пары, а не каждого значения отдельно"}'::jsonb, 'CD', 'Составные ключи задают правила для комбинаций значений. Это позволяет, например, идентифицировать строку заказа парой «номер заказа и номер позиции».', '{"A":"Имена могут различаться; важны состав ссылки и совместимость типов.","B":"У таблицы один первичный ключ, который может включать несколько столбцов.","C":"Составная ссылка проверяет соответствующую комбинацию значений.","D":"Один order_id может встречаться в нескольких строках с разными line_no."}'::jsonb;

DO $check$
DECLARE candidate record; matches integer;
BEGIN
    FOR candidate IN SELECT * FROM question_seed LOOP
        SELECT count(*) INTO matches FROM questions q
        WHERE regexp_replace(trim(q.question_text), '[[:space:]]+', ' ', 'g') =
              regexp_replace(trim(candidate.question_text), '[[:space:]]+', ' ', 'g');
        IF matches > 1 OR (matches = 1 AND NOT EXISTS (
            SELECT 1 FROM questions q WHERE q.question_text = candidate.question_text
              AND q.category_id = candidate.category_id AND q.options = candidate.options
              AND q.correct_answer = candidate.correct_answer AND q.explanation = candidate.explanation
              AND q.option_notes = candidate.option_notes
        )) THEN
            RAISE EXCEPTION 'Конфликт содержимого или повтор нового вопроса';
        END IF;
    END LOOP;
END
$check$;

INSERT INTO questions(category_id, question_text, options, correct_answer, explanation, option_notes)
SELECT n.* FROM question_seed n
WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.question_text = n.question_text);

DO $check$
BEGIN
    IF (SELECT count(*) FROM questions q JOIN question_seed n ON q.question_text = n.question_text) <> 30 THEN
        RAISE EXCEPTION 'Неверное число вопросов после добавления';
    END IF;
END
$check$;

COMMIT;
